 // 05:00 - 06:00 PM\n  SLOT_06_07 // 06:00 - 07:00 PM\n  SLOT_07_08 // 07:00 - 08:00 PM\n  CUSTOM\n}\n\nenum PainSide {\n  RIGHT\n  LEFT\n  BOTH\n}\n\nenum PainType {\n  SHARP\n  DULL\n  BURNING\n  RADIATING\n}\n\nenum RomStatus {\n  NORMAL\n  RESTRICTED\n}\n\nenum PackageStatus {\n  ACTIVE\n  COMPLETED\n  EXPIRED\n  CANCELLED\n}\n\nenum PunctualityStatus {\n  ON_TIME\n  MODERATE_LATE\n  SEVERE_LATE\n}\n\n// --------------------------------------------------------\n// USER & AUTHENTICATION\n// --------------------------------------------------------\n\nmodel User {\n  id       String @id @default(cuid())\n  name     String\n  role     Role\n  password String\n\n  // Relations\n  sessions           Session[]\n  auditLogs          AuditLog[]\n  registeredPatients Patient[]            @relation("PatientRegistrar")\n  doctorSerials      Serial[]             @relation("DoctorSerials")\n  handlerSerials     Serial[]             @relation("HandlerSerials")\n  createdSerials     Serial[]             @relation("CreatedSerials")\n  doctorAssessments  ClinicalAssessment[] @relation("DoctorAssessments")\n  conductedSessions  TreatmentSession[]   @relation("HandlerSessions")\n  cashierBillings    BillingRecord[]      @relation("CashierBillings")\n  auditedBillings    BillingRecord[]      @relation("AuditedBillings")\n\n  // Room Relations\n  doctorRooms  Room[] @relation("RoomCurrentDoctor")\n  handlerRooms Room[] @relation("RoomCurrentHandler")\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nmodel Session {\n  id    String @id @default(cuid())\n  token String @unique\n\n  userId String\n  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  ipAddress String?\n  userAgent String?\n  device    String?\n  browser   String?\n  os        String?\n\n  expiresAt    DateTime\n  revokedAt    DateTime?\n  lastAccessAt DateTime?\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n}\n\nmodel AuditLog